package com.gymmind.membership.application;
import com.gymmind.audit.application.AuditRecorder; import com.gymmind.membership.domain.model.*; import com.gymmind.membership.domain.repository.*; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.shared.security.CurrentActor; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.Instant; import java.util.Optional; import java.util.Set; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class MemberMembershipServiceTest { @Test void grantCreatesTenantScopedEntitlement(){MemberMembershipRepository memberships=mock(MemberMembershipRepository.class); MembershipPackageRepository packages=mock(MembershipPackageRepository.class); when(packages.findByTenantIdAndId(11L,8L)).thenReturn(Optional.of(MembershipPackage.create(11L,"10次","COUNT",10,null,new BigDecimal("99"),"CNY"))); when(memberships.save(any(MemberMembership.class))).thenAnswer(i->i.getArgument(0)); MemberMembershipService service=new DefaultMemberMembershipService(memberships,packages,mock(AuditRecorder.class)); MemberMembershipView view=service.grant(admin(11L),new GrantMembershipCommand(null,41L,8L,Instant.now(),null)); assertThat(view.tenantId()).isEqualTo(11L); assertThat(view.remainingCount()).isEqualTo(10); verify(memberships).save(any(MemberMembership.class)); } private static CurrentActor admin(long t){return new CurrentActor(1L,t,Set.of(RoleCode.GYM_ADMIN),Set.of("membership:write"),0L,"token");}}
